export default function StudentDashboardRef() {
  const rootRef = useRef(null);
  useEffect(() => {
    const styleEl = document.createElement('style');
    styleEl.textContent = styleText;
    document.head.appendChild(styleEl);
    const scriptEl = document.createElement('script');
    scriptEl.textContent = scriptText;
    document.body.appendChild(scriptEl);
    const placeholder = rootRef.current && rootRef.current.querySelector('.alumnex-official-logo');
    if (placeholder) {
      const r = createRoot(placeholder);
      r.render(<AlumnexLogo />);
    }
    return () => {
      if (styleEl.parentNode) styleEl.parentNode.removeChild(styleEl);
      if (scriptEl.parentNode) scriptEl.parentNode.removeChild(scriptEl);
    };
  }, []);
  return (
    <div ref={rootRef} className="alumnex-ref-root" dangerouslySetInnerHTML={{ __html: bodyHtml }} />
  );
}
